"use strict";

/*
 * cnotes.h site pages: home (index.html) and releases (releases.html).
 * Loads library.json (generated by `./nob doc`) and formats comments of cnotes.h describing the library
 * as a whole: the header comment the file starts with, and the comments at the very end of it.
 *
 * Comment text format, as written in cnotes.h:
 *   name - vX.Y.Z - License - url      first line of the header
 *   # Title, ## Title                  headings
 *   - item text                        list item, "- TERM    text" with 2+ spaces is a term and its text
 *   TERM    text                       row of a table, term and text separated by 2+ spaces
 *   more indented line                 continues the item or row above
 *   X.Y.Z (date) change                release in revision history, following lines are its changes
 * Anything else is a paragraph, blank lines separate paragraphs.
 */
(function () {
    const DATA_URL = "library.json";

    /* ---------- Helpers ---------- */

    const HTML_ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

    function escapeHtml(text) {
        return String(text).replace(/[&<>"']/g, (c) => HTML_ESCAPES[c]);
    }

    // Inline text: `code` is shown as code, urls become links.
    function inline(text) {
        return text.split(/(`[^`]+`|https?:\/\/[^\s)]+)/).map((part) => {
            if (part.startsWith("`") && part.endsWith("`") && part.length > 1) return `<code>${escapeHtml(part.slice(1, -1))}</code>`;
            if (/^https?:\/\//.test(part)) return `<a href="${escapeHtml(part)}">${escapeHtml(part)}</a>`;
            return escapeHtml(part);
        }).join("");
    }

    // Lines of text with indentation common to all non-blank lines removed, surrounding blank lines dropped.
    function dedentLines(text) {
        const lines = text.replace(/\t/g, "    ").split("\n").map((l) => l.trimEnd());
        while (lines.length && !lines[0]) lines.shift();
        while (lines.length && !lines[lines.length - 1]) lines.pop();
        const indents = lines.filter(Boolean).map((l) => l.match(/^ */)[0].length);
        const cut = indents.length ? Math.min(...indents) : 0;
        return lines.map((l) => l.slice(cut));
    }

    function indentOf(line) {
        return line.match(/^ */)[0].length;
    }

    // Splits "TERM    text" on the first gap of 2+ spaces, null if there is no such gap.
    function splitTerm(text) {
        const match = /^(\S(?:.*?\S)?)\s{2,}(\S.*)$/.exec(text);
        return match ? { term: match[1], text: match[2] } : null;
    }


    /* ---------- Generic comment text ---------- */

    // Parses lines into blocks: { type: "heading", level, text }, { type: "p", text },
    // { type: "list", items }, { type: "rows", items }, items are { term, text }.
    function parseBlocks(lines) {
        const blocks = [];
        let open = null;

        for (const line of lines) {
            const trimmed = line.trim();
            const indent = indentOf(line);

            if (!trimmed) {
                open = null;
                continue;
            }

            const heading = /^(#{1,3})\s+(.*)$/.exec(trimmed);
            if (heading) {
                blocks.push({ type: "heading", level: heading[1].length, text: heading[2] });
                open = null;
                continue;
            }

            if (trimmed.startsWith("- ")) {
                if (!open || open.type !== "list" || open.indent !== indent) {
                    open = { type: "list", indent, items: [] };
                    blocks.push(open);
                }
                const text = trimmed.slice(2).trim();
                open.items.push(splitTerm(text) || { term: "", text });
                continue;
            }

            // Deeper indented line continues the item or row above it.
            if (open && (open.type === "list" || open.type === "rows") && indent > open.indent) {
                const last = open.items[open.items.length - 1];
                last.text += " " + trimmed;
                continue;
            }

            const row = splitTerm(trimmed);
            if (row) {
                if (!open || open.type !== "rows") {
                    open = { type: "rows", indent, items: [] };
                    blocks.push(open);
                }
                open.items.push(row);
                continue;
            }

            if (!open || open.type !== "p") {
                open = { type: "p", text: "" };
                blocks.push(open);
            }
            open.text += (open.text ? " " : "") + trimmed;
        }

        return blocks;
    }

    function renderTerm(term) {
        return `<code>${escapeHtml(term.replace(/^`|`$/g, ""))}</code>`;
    }

    function renderDefs(items) {
        return `<dl class="defs">` + items.map((item) =>
            `<div><dt>${renderTerm(item.term)}</dt><dd>${inline(item.text)}</dd></div>`
        ).join("") + `</dl>`;
    }

    // Page section: title in the left column, content on the right.
    function block(title, body, options = {}) {
        const id = options.id ? ` id="${escapeHtml(options.id)}"` : "";
        return `<section class="block"${id}>` +
            (title ? `<h2 class="block-title">${inline(title)}</h2>` : `<div></div>`) +
            `<div class="block-body ${options.bodyClass ?? "prose"}">${body}</div></section>`;
    }

    // Every "# Title" of the text starts its own page section, text before the first one goes untitled.
    function renderSections(blocks) {
        const sections = [];
        for (const b of blocks) {
            if (b.type === "heading" && b.level === 1) sections.push({ title: b.text, blocks: [] });
            else {
                if (!sections.length) sections.push({ title: "", blocks: [] });
                sections[sections.length - 1].blocks.push(b);
            }
        }
        return sections.map((sec) => block(sec.title, renderBlocks(sec.blocks))).join("");
    }

    function renderBlocks(blocks) {
        return blocks.map((b) => {
            switch (b.type) {
            case "heading": return b.level === 1 ? `<h2 class="eyebrow">${inline(b.text)}</h2>` : `<h3>${inline(b.text)}</h3>`;
            case "p":       return `<p>${inline(b.text)}</p>`;
            case "rows":    return renderDefs(b.items);
            case "list":
                // A list with terms reads better as a table of terms.
                if (b.items.every((i) => i.term)) return renderDefs(b.items);
                return `<ul>` + b.items.map((i) =>
                    `<li>${i.term ? renderTerm(i.term) + " " : ""}${inline(i.text)}</li>`
                ).join("") + `</ul>`;
            }
            return "";
        }).join("");
    }


    /* ---------- Library comments ---------- */

    // Header comment: "name - vX.Y.Z - License - url" line, first paragraph is the lead, the rest is overview.
    function parseHeader(text) {
        const lines = dedentLines(text);
        const meta = (lines.shift() || "").split(/\s+-\s+/).map((s) => s.trim());
        const blocks = parseBlocks(lines);

        const leadIndex = blocks.findIndex((b) => b.type === "p");
        const lead = leadIndex === 0 ? blocks.shift().text : "";

        return {
            name:    meta[0] || "",
            version: (meta.find((m) => /^v?\d+\.\d+\.\d+/.test(m)) || "").replace(/^v/, ""),
            license: meta.find((m) => /license/i.test(m)) || "",
            url:     meta.find((m) => /^https?:\/\//.test(m)) || "",
            lead,
            blocks,
        };
    }

    // Trailing comment: titled by its first line. It is the revision history if it has release lines.
    function parseTrailer(text) {
        const lines = dedentLines(text);
        const title = (lines.shift() || "").trim().replace(/:$/, "");
        const releaseRe = /^(\d+\.\d+\.\d+)\s*(?:\(([^)]*)\))?\s*(.*)$/;

        if (lines.some((l) => releaseRe.test(l.trim()))) {
            const releases = [];
            for (const line of lines) {
                const trimmed = line.trim();
                if (!trimmed) continue;
                const match = releaseRe.exec(trimmed);
                if (match) {
                    releases.push({ version: match[1], date: match[2] || "", changes: match[3] ? [match[3]] : [] });
                } else if (releases.length) {
                    releases[releases.length - 1].changes.push(trimmed);
                }
            }
            return { type: "releases", title, releases };
        }

        return { type: "section", title, blocks: parseBlocks(lines) };
    }

    function load(data) {
        const trailer = (Array.isArray(data.trailer) ? data.trailer : []).map(parseTrailer);
        const history = trailer.find((t) => t.type === "releases");
        return {
            header:   parseHeader(typeof data.header === "string" ? data.header : ""),
            releases: history ? history.releases : [],
            historyTitle: history ? history.title : "Revision history",
            sections: trailer.filter((t) => t.type === "section"),
        };
    }


    /* ---------- Rendering ---------- */

    function fill(id, html) {
        const el = document.getElementById(id);
        if (el) el.innerHTML = html;
        return el;
    }

    function renderRelease(release, isLatest) {
        return `
            <article class="release" id="v${escapeHtml(release.version)}">
                <header class="release-head">
                    <h3 class="release-version">${escapeHtml(release.version)}</h3>
                    ${release.date ? `<time>${escapeHtml(release.date)}</time>` : ""}
                    ${isLatest ? `<span class="badge">Latest</span>` : ""}
                </header>
                <ul class="changes">${release.changes.map((c) => `<li>${inline(c)}</li>`).join("")}</ul>
            </article>`;
    }

    function renderMeta(lib) {
        const h = lib.header;
        const latest = lib.releases[0];
        const items = [];
        if (h.version) items.push(`<span class="badge version">v<b>${escapeHtml(h.version)}</b></span>`);
        if (latest && latest.date && latest.version === h.version) items.push(`<span class="badge">Released <b>${escapeHtml(latest.date)}</b></span>`);
        if (h.license) items.push(`<a class="badge" href="releases.html#license">${escapeHtml(h.license)}</a>`);
        if (h.url) items.push(`<a class="badge" href="${escapeHtml(h.url)}">Source</a>`);
        return items.join("");
    }

    // Initial development notice, versions 0.y.z have no stable public API.
    function renderStatus(version) {
        if (!/^0\./.test(version)) return "";
        return `<strong>Initial development.</strong> Versions <code>0.y.z</code> may change anything at any time, public API is not stable.`;
    }

    function renderHome(lib) {
        fill("meta", renderMeta(lib));
        if (lib.header.lead) fill("lead", inline(lib.header.lead));

        const status = fill("status", renderStatus(lib.header.version));
        if (status) status.hidden = !status.innerHTML;

        fill("overview", renderSections(lib.header.blocks));

        const latest = lib.releases[0];
        if (latest) {
            fill("latest", block("Latest release", renderRelease(latest, false) +
                `<p class="more"><a href="releases.html">All releases</a></p>`, { bodyClass: "" }));
        }
    }

    function renderReleases(lib) {
        fill("meta", renderMeta(lib));
        const releases = lib.releases.map((r, i) => renderRelease(r, i === 0)).join("")
            || `<p class="notice">No releases found.</p>`;
        fill("releases", block(lib.historyTitle, `<div class="releases">${releases}</div>`, { bodyClass: "" }));

        fill("sections", lib.sections.map((s) => {
            const id = /license/i.test(s.title) ? "license" : s.title.toLowerCase().replace(/[^a-z0-9]+/g, "-");
            return block(s.title, renderBlocks(s.blocks), { id, bodyClass: id === "license" ? "license" : "prose" });
        }).join(""));
    }

    function showError(error) {
        const fromFile = location.protocol === "file:";
        const el = fill("site-error", `<strong>Could not load ${DATA_URL}.</strong> ${escapeHtml(error.message || String(error))} ` +
            (fromFile
                ? `Serve the folder instead: <code>python3 -m http.server -d doc 8000</code>`
                : `Generate it with <code>./nob doc</code> and reload the page.`));
        if (el) el.hidden = false;
    }

    async function main() {
        const page = document.body.dataset.page;
        try {
            const response = await fetch(DATA_URL, { cache: "no-cache" });
            if (!response.ok) throw new Error(`Server responded with ${response.status} ${response.statusText}.`);
            const lib = load(await response.json());
            if (page === "home") renderHome(lib);
            if (page === "releases") renderReleases(lib);
        } catch (error) {
            showError(error);
        }
    }

    main();
})();
